// Fission products: the widgets of "Air on hot graphite" (chem-air.html),
// "Steam on graphite and bare kernels" (chem-steam.html) and "Into the
// source term" (atops-source-term.html). Each registers with
// Lesson.widget(id, make).
// Data: chemhand-data.js (generated by crates/dhoby-ghaut/examples/
// lesson_chemistry_handoff from boon_lay::chemistry and the dispersion
// demo's recorded source term). NO physics here: every number drawn is a
// recorded value at a recorded temperature and pressure; the controls pick
// among the recorded pressures, they do not interpolate between them.
// Plot helpers: plot-kit.js. Drawing is a table lookup, so no worker.
(function () {
  "use strict";
  var L = window.Lesson, css = L.css, el = L.el;
  var LP = window.LessonPlot, sci = LP.sci, Box = LP.Box, decTicks = LP.decTicks, linTicks = LP.linTicks, legend = LP.legend;
  var CD = function () { return window.CHEMHAND_DATA; };
  var DOT = [2, 4], DASH = [8, 5];
  var AIR = "#b85c38", STEAM = "#2f7fd8", KERN = "#2a9d55", RED = "#c0392b";

  // Draw ys against xs, dotted where flag[i] is truthy (inside the measured
  // range) and dashed where it is not (extrapolated), as the demo's
  // chemistry rung does. Segments overlap one point so they join.
  function flagged(B, ctx, xs, ys, flag, col, w) {
    var i = 0;
    while (i < xs.length) {
      var f = !!flag[i], j = i;
      while (j + 1 < xs.length && !!flag[j + 1] === f) j++;
      var end = Math.min(j + 1, xs.length - 1);
      B.line(ctx, xs.slice(i, end + 1), ys.slice(i, end + 1), col, w || 2.5, f ? DOT : DASH);
      i = j + 1;
    }
  }
  function band(B, ctx, xs, flag, col) {
    var lo = null, hi = null;
    xs.forEach(function (x, i) { if (flag[i]) { if (lo === null) lo = x; hi = x; } });
    if (lo === null) return;
    ctx.fillStyle = col; ctx.globalAlpha = 0.09;
    ctx.fillRect(B.X(lo), B.y0, B.X(hi) - B.X(lo), B.y1 - B.y0); ctx.globalAlpha = 1;
  }
  function kpaLabel(p) { return (p < 1 ? p.toFixed(p < 0.3 ? 2 : 1) : p >= 21 ? p.toFixed(1) : String(p)) + " kPa"; }
  function split(w, h) {
    // Two plots: side by side when wide, stacked on a phone.
    if (w >= 720) return [[58, 54, w / 2 - 14, h - 40], [w / 2 + 52, 54, w - 12, h - 40]];
    var mid = 54 + (h - 54 - 40) / 2;
    return [[58, 54, w - 12, mid - 24], [58, mid + 20, w - 12, h - 40]];
  }

  // ─── Air on hot graphite ──────────────────────────────────────────────
  function airW(root) {
    var st = { k: 5, all: false };
    var frame = new L.Frame(root, {
      reset: function () { st.k = 5; }, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var D = CD(), A = D.air, c = A.curves[st.k], xs = D.tC, r = split(w, h);
        var z = Math.max(0, (zoom - 1) * 3);
        var B1 = new Box(r[0][0], r[0][1], r[0][2], r[0][3], [400, 1600], [-14 + z, 1], false, true);
        band(B1, ctx, xs, c.inside, AIR);
        B1.frame(ctx, "temperature (°C)", "kinetic rate (1/s)", linTicks(400, 1600, 300), decTicks(B1.yr[0], 1, 3));
        if (st.all) A.curves.forEach(function (o, k) { if (k !== st.k) B1.line(ctx, xs, o.rate, "#bbb", 1); });
        flagged(B1, ctx, xs, c.rate, c.inside, AIR);
        var y = legend(ctx, [["inside 597–694 °C (measured)", AIR, DOT], ["extrapolated", AIR, DASH]], r[0][0], 16, r[0][2] - r[0][0]);
        ctx.fillStyle = css("--fg", "#1d2125"); ctx.font = "bold 11px system-ui, sans-serif";
        ctx.fillText("IG-110 in air: fraction of the graphite per second, O₂ " + kpaLabel(c.o2kPa), r[0][0], y + 2);
        // Right/bottom: carbon gasified, kinetic against supply.
        var B2 = new Box(r[1][0], r[1][1], r[1][2], r[1][3], [400, 1600], [-6 + z, 4], false, true);
        B2.frame(ctx, "temperature (°C)", "carbon gasified (mol/s)", linTicks(400, 1600, 300), decTicks(B2.yr[0], 4, 2));
        B2.line(ctx, xs, c.kineticMol, AIR, 1.2, DASH);
        B2.line(ctx, [400, 1600], [A.supplyMolPerS, A.supplyMolPerS], css("--muted", "#5b636b"), 1.2, [3, 3]);
        B2.line(ctx, xs, c.gasifiedMol, css("--fg", "#1d2125"), 3);
        if (c.crossoverC !== null) {
          var px = B2.X(c.crossoverC), py = B2.Y(A.supplyMolPerS);
          ctx.fillStyle = RED; ctx.beginPath(); ctx.arc(px, py, 4.5, 0, 7); ctx.fill();
          ctx.font = "11px system-ui, sans-serif"; ctx.fillText(c.crossoverC.toFixed(0) + " °C", px + 6, py - 6);
        }
        var y2 = r[1][1] - 36 > 0 && w >= 720 ? 16 : r[1][1] - 6;
        legend(ctx, [["what the code returns", css("--fg", "#1d2125")], ["kinetic, unlimited O₂", AIR, DASH], ["O₂ supply, 1 mol/s", css("--muted", "#5b636b"), [3, 3]]], r[1][0], w >= 720 ? 16 : y2, r[1][2] - r[1][0]);
        var i900 = xs.indexOf(900);
        return "O₂ " + kpaLabel(c.o2kPa) + ": at 900 °C the kinetics would take " + sci(c.kineticMol[i900]) + " mol/s of carbon from 5000 kg of graphite; the supply allows 1 mol/s, so the supply sets the rate from " + (c.crossoverC === null ? "—" : c.crossoverC.toFixed(0) + " °C") + " up. Dotted: inside the measured range; dashed: extrapolated.";
      },
      panel: function (body, redraw) {
        var A = CD().air;
        L.slider(body, "O₂ partial pressure (recorded values)", 0, A.curves.length - 1, 1, st.k, function (v) { st.k = v; redraw(); return kpaLabel(A.curves[v].o2kPa); });
        L.toggle(body, "Show the other pressures (grey)", st.all, function (v) { st.all = v; redraw(); });
        body.append(el("p", { "class": "w-note" }, "5000 kg of graphite and 1 mol/s of O₂ are boon-lay's own check values, not a plant's. 21.3 kPa is air at 1 atm, the measurement's own condition."));
      }
    });
    return frame;
  }

  // ─── Steam on graphite and bare kernels ───────────────────────────────
  function steamW(root) {
    var st = { k: 4, h2: 0 };
    var frame = new L.Frame(root, {
      reset: function () { st.k = 4; st.h2 = 0; }, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var D = CD(), s = D.steam[st.k], g = s.graphite[st.h2], xs = D.tC, r = split(w, h);
        var z = Math.max(0, (zoom - 1) * 3);
        var B1 = new Box(r[0][0], r[0][1], r[0][2], r[0][3], [400, 1600], [-14 + z, -2], false, true);
        band(B1, ctx, xs, g.inside, STEAM);
        B1.frame(ctx, "temperature (°C)", "graphite rate (1/s)", linTicks(400, 1600, 300), decTicks(B1.yr[0], -2, 3));
        flagged(B1, ctx, xs, g.rate, g.inside, STEAM);
        var y = legend(ctx, [["inside the measured box", STEAM, DOT], ["extrapolated", STEAM, DASH]], r[0][0], 16, r[0][2] - r[0][0]);
        ctx.fillStyle = css("--fg", "#1d2125"); ctx.font = "bold 11px system-ui, sans-serif";
        ctx.fillText("C + H₂O → CO + H₂, steam " + kpaLabel(s.kPa) + (g.h2kPa ? ", H₂ 1 kPa" : ", no H₂"), r[0][0], y + 2);
        var B2 = new Box(r[1][0], r[1][1], r[1][2], r[1][3], [400, 1600], [-6 + z, 0.3], false, true);
        var inFit = s.hydrolysisFlag.map(function (f) { return f === 0; });
        band(B2, ctx, xs, inFit, KERN);
        B2.frame(ctx, "temperature (°C)", "stored gas released", linTicks(400, 1600, 300), decTicks(B2.yr[0], 0, 2));
        flagged(B2, ctx, xs, s.hydrolysis, inFit, KERN);
        ctx.fillStyle = RED;
        xs.forEach(function (x, i) { if (s.hydrolysisFlag[i] === 2) ctx.fillRect(B2.X(x) - 2, B2.Y(1) - 2, 4, 4); });
        legend(ctx, [["bare kernel, inside the fit", KERN, DOT], ["extrapolated", KERN, DASH], ["clamped to the whole inventory", RED]], r[1][0], w >= 720 ? 30 : r[1][1] - 6, r[1][2] - r[1][0]);
        var nC = s.hydrolysisFlag.filter(function (f) { return f === 2; }).length;
        var nIn = g.inside.filter(function (f) { return f; }).length;
        return "Steam " + kpaLabel(s.kPa) + ": the graphite law is inside its measured box at " + nIn + " of " + xs.length + " temperatures; the kernel fit returns the whole stored inventory (red) at " + nC + " of them. Dotted: inside the fitted range; dashed: extrapolated.";
      },
      panel: function (body, redraw) {
        var S = CD().steam;
        L.slider(body, "Steam partial pressure (recorded values)", 0, S.length - 1, 1, st.k, function (v) { st.k = v; redraw(); return kpaLabel(S[v].kPa); });
        L.buttons(body, "Hydrogen", [[0, "none"], [1, "1 kPa"]], st.h2, function (v) { st.h2 = v; redraw(); });
        body.append(el("p", { "class": "w-note" }, "Measured: graphite 850–1100 °C at 0.5–20 kPa steam (Wang & Sun 2023); kernel 820–1040 °C at 2.8 Pa–1.05 kPa (IAEA-TECDOC-978). A water-ingress accident sits at hundreds of kPa."));
      }
    });
    return frame;
  }

  // ─── Into the source term ─────────────────────────────────────────────
  var NCOL = { "Xe-133": "#2f7fd8", "I-131": "#7a4cc2", "I-133": "#7a4cc2", "Cs-137": "#2a9d55", "Cs-134": "#2a9d55", "Ag-110m": "#7f8c8d" };
  function sourceW(root) {
    var st = { show: "released" };
    var frame = new L.Frame(root, {
      reset: function () { st.show = "released"; }, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var S = CD().source, N = S.nuclides, top = 40, frac = st.show === "fraction";
        var lo = frac ? -5 : 9, hi = frac ? 0 : 17;
        var z = Math.max(0, (zoom - 1) * 2);
        var B = new Box(66, top, w - 12, h - 44, [0, N.length], [lo + z, hi], false, true);
        B.frame(ctx, "", frac ? "released / core inventory" : "activity (Bq)", [], decTicks(B.yr[0], hi, frac ? 1 : 2));
        var bw = (B.x1 - B.x0) / N.length;
        ctx.font = "11px system-ui, sans-serif";
        N.forEach(function (n, i) {
          var x = B.x0 + i * bw;
          function bar(v, off, wd, col, alpha) {
            var y = B.Y(v), y0 = B.y1;
            ctx.globalAlpha = alpha; ctx.fillStyle = col;
            ctx.fillRect(x + off, Math.min(y, y0), wd, Math.abs(y0 - y)); ctx.globalAlpha = 1;
          }
          if (frac) bar(n.fraction, bw * 0.2, bw * 0.6, NCOL[n.name] || "#888", 0.9);
          else {
            bar(n.inventoryBq, bw * 0.12, bw * 0.36, NCOL[n.name] || "#888", 0.25);
            bar(n.releasedBq, bw * 0.52, bw * 0.36, NCOL[n.name] || "#888", 0.95);
          }
          ctx.fillStyle = css("--fg", "#1d2125");
          var lab = n.name; ctx.fillText(lab, x + bw / 2 - ctx.measureText(lab).width / 2, B.y1 + 14);
          var v = frac ? n.fraction : n.releasedBq, t = sci(v, 3);
          ctx.fillStyle = css("--muted", "#5b636b"); ctx.font = "10px system-ui, sans-serif";
          ctx.fillText(t, x + bw / 2 - ctx.measureText(t).width / 2, Math.max(B.y0 + 10, B.Y(v) - 4));
          ctx.font = "11px system-ui, sans-serif";
        });
        ctx.fillStyle = css("--fg", "#1d2125"); ctx.font = "bold 11px system-ui, sans-serif";
        ctx.fillText(frac ? "Fraction of the core inventory released in 96 h" : "Released in 96 h (solid) beside the core inventory (pale)", 66, 22);
        return "Recorded, not recomputed: " + S.provenance + ". These six carry " + sci(S.sixBq) + " of the " + sci(S.totalBq) + " Bq released in all. A deliberately pessimistic bounding case, never a dose to a person.";
      },
      panel: function (body, redraw) {
        L.buttons(body, "Show", [["released", "Activity (Bq)"], ["fraction", "Fraction of inventory"]], st.show, function (v) { st.show = v; redraw(); });
        body.append(el("p", { "class": "w-note" }, "HTR-10 air ingress, bounding case B: the whole core at 1400 °C, every particle exposed, the KORA measured failures added by hand. Inventory: Liu & Cao 2002, Table 1."));
      }
    });
    return frame;
  }

  // ─── Numbers in the prose ─────────────────────────────────────────────
  function fillCh() {
    var D = CD(), A = D.air, air = A.curves[A.curves.length - 1], one = A.curves.filter(function (c) { return c.o2kPa === 1; })[0];
    var S = D.source, nuc = function (n) { return S.nuclides.filter(function (x) { return x.name === n; })[0]; };
    var map = {
      r650: sci(D.airAt.r650, 5) + " /s", r900: sci(D.airAt.r900) + " /s", ratio900: D.airAt.ratio900.toFixed(0),
      crossAir: air.crossoverC.toFixed(0) + " °C", cross1: one.crossoverC.toFixed(0) + " °C",
      heatSupply: (Math.abs(A.co2kJPerMol) * A.supplyMolPerS).toFixed(0) + " kW",
      s1050: sci(D.steamAt.r1050, 4) + " /s", h2ratio: (D.steamAt.r1050H2 / D.steamAt.r1050).toFixed(2),
      whole770: D.wholeInventory.at770.toFixed(1) + " kPa", whole1000: D.wholeInventory.at1000.toFixed(1) + " kPa",
      srcTotal: sci(S.totalBq) + " Bq", srcSix: (100 * S.sixBq / S.totalBq).toFixed(0) + " %",
      fXe: sci(nuc("Xe-133").fraction), fI131: sci(nuc("I-131").fraction), fCs137: sci(nuc("Cs-137").fraction), fAg: sci(nuc("Ag-110m").fraction),
      relI131: sci(nuc("I-131").releasedBq) + " Bq", relCs137: sci(nuc("Cs-137").releasedBq) + " Bq"
    };
    document.querySelectorAll("[data-ch]").forEach(function (n) { var k = n.getAttribute("data-ch"); if (k in map) n.textContent = map[k]; });
  }
  L.widget("ch-numbers", fillCh);
  L.widget("ch-air", airW);
  L.widget("ch-steam", steamW);
  L.widget("ch-source", sourceW);
})();
